$s='(y + 1)'; $t=$null;$e=$null; $ast=[System.Management.Automation.Language.Parser]::ParseInput($s,[ref]$t,[ref]$e); $cmdExpr=$ast.EndBlock.Statements[0].PipelineElements[0]; $bin=$cmdExpr.Expression; Write-Host "CmdExpr Type:"$cmdExpr.GetType().Name; Write-Host "Inner Type:"$bin.GetType().Name; $bin | ForEach-Object { Write-Host "Left:"$_.Left.GetType().Name; Write-Host "Left Text:"$_.Left.Extent.Text; Write-Host "Right:"$_.Right.GetType().Name; Write-Host "Right Text:"$_.Right.Extent.Text }
